<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { message, Modal } from 'ant-design-vue'
import { BarcodeOutlined, CheckCircleOutlined, DatabaseOutlined, FileDoneOutlined, FundOutlined, PlusOutlined, ToolOutlined } from '@ant-design/icons-vue'
import api from '@/api/client'
import PageBackButton from '@/components/PageBackButton.vue'

type AssetStatus = '在用' | '闲置' | '维修中' | '待处置'
interface Asset { id:number; asset_code:string; name:string; category:string; department:string; owner:string; location:string; status:AssetStatus; value:number; purchase_date?:string; last_inventory_at?:string }
interface Task { id:number; name:string; scope:string; owner:string; status:string; due_date?:string; total_count:number; checked_count:number; exception_count:number }
interface AssetException { id:number; asset_id:number; asset_code:string; asset_name:string; department:string; type:string; description:string; status:string; resolution?:string }

const activeTab = ref('overview'); const loading = ref(false); const keyword = ref(''); const statusFilter = ref('全部')
const assets = ref<Asset[]>([]); const tasks = ref<Task[]>([]); const exceptions = ref<AssetException[]>([]); const summary = ref({ asset_count:0, total_value:0, inventory_completion:0, exception_count:0 })
const assetDrawerOpen = ref(false); const taskDrawerOpen = ref(false); const editingId = ref<number | null>(null); const exceptionModalOpen = ref(false); const resolving = ref<AssetException | null>(null); const resolution = ref('')
const assetForm = reactive({ asset_code:'', name:'', category:'办公设备', department:'', owner:'', location:'', status:'在用' as AssetStatus, value:0 })
const taskForm = reactive({ name:'', scope:'', owner:'', due_date:'', status:'草稿' })
const statuses = ['全部','在用','闲置','维修中','待处置']
const filteredAssets = computed(() => assets.value.filter(item => (!keyword.value || `${item.asset_code}${item.name}${item.department}${item.owner}`.toLowerCase().includes(keyword.value.toLowerCase())) && (statusFilter.value === '全部' || item.status === statusFilter.value)))
const statusColor:Record<string,string> = { 在用:'green', 闲置:'gold', 维修中:'orange', 待处置:'red' }
const exceptionColor:Record<string,string> = { 待核实:'red', 处理中:'orange', 已归档:'green' }

async function loadData() { loading.value = true; try { const [s,a,t,e] = await Promise.all([api.get('/api/v1/assets/summary'),api.get('/api/v1/assets'),api.get('/api/v1/assets/inventory-tasks'),api.get('/api/v1/assets/exceptions')]); summary.value=s.data.data; assets.value=a.data.data; tasks.value=t.data.data; exceptions.value=e.data.data } catch (error:any) { message.error(error.response?.data?.detail || '资产数据加载失败') } finally { loading.value=false } }
function openAsset(asset?:Asset) { editingId.value=asset?.id || null; Object.assign(assetForm, asset ? { ...asset, asset_code:asset.asset_code } : { asset_code:'', name:'', category:'办公设备', department:'', owner:'', location:'', status:'在用', value:0 }); assetDrawerOpen.value=true }
async function saveAsset() { try { if(editingId.value) await api.patch(`/api/v1/assets/${editingId.value}`, assetForm); else await api.post('/api/v1/assets', assetForm); message.success('资产已保存'); assetDrawerOpen.value=false; await loadData() } catch(error:any) { message.error(error.response?.data?.detail || '保存失败') } }
function removeAsset(id:number) { Modal.confirm({ title:'确认删除资产？', content:'删除后台账记录将无法恢复。', onOk:async()=>{ try{ await api.delete(`/api/v1/assets/${id}`); message.success('已删除'); await loadData() }catch(error:any){message.error(error.response?.data?.detail || '删除失败')} } }) }
async function saveTask() { try { await api.post('/api/v1/assets/inventory-tasks', taskForm); message.success('盘点任务已创建'); taskDrawerOpen.value=false; Object.assign(taskForm,{name:'',scope:'',owner:'',due_date:'',status:'草稿'}); await loadData() } catch(error:any){message.error(error.response?.data?.detail || '创建失败')} }
function openResolve(item:AssetException) { resolving.value=item; resolution.value=item.resolution || ''; exceptionModalOpen.value=true }
async function resolveException() { if(!resolving.value || !resolution.value.trim()) return message.warning('请输入处置结果'); try { await api.post(`/api/v1/assets/exceptions/${resolving.value.id}/resolve`,{resolution:resolution.value}); message.success('异常已归档'); exceptionModalOpen.value=false; await loadData() } catch(error:any){message.error(error.response?.data?.detail || '归档失败')} }
onMounted(loadData)
</script>

<template>
  <div class="page-frame business-page">
    <header class="page-heading"><div><p class="eyebrow">ASSET LIFECYCLE</p><h1>全资产管理</h1><p>真实数据库驱动的资产台账、盘点任务和异常处置工作台。</p></div><div class="heading-actions"><PageBackButton /><a-button type="primary" @click="taskDrawerOpen=true"><BarcodeOutlined /> 新建盘点任务</a-button></div></header>
    <a-spin :spinning="loading">
      <section class="metric-grid"><a-card class="metric-card" :bordered="false"><DatabaseOutlined /><span>资产总值</span><strong>{{ (summary.total_value / 10000).toFixed(1) }} 万</strong></a-card><a-card class="metric-card" :bordered="false"><FileDoneOutlined /><span>台账资产</span><strong>{{ summary.asset_count }} 件</strong></a-card><a-card class="metric-card" :bordered="false"><FundOutlined /><span>盘点完成率</span><strong>{{ summary.inventory_completion }}%</strong></a-card><a-card class="metric-card" :bordered="false"><ToolOutlined /><span>异常待处理</span><strong>{{ summary.exception_count }} 条</strong></a-card></section>
      <a-tabs v-model:active-key="activeTab" class="business-tabs">
        <a-tab-pane key="overview" tab="运营总览"><section class="business-grid two-columns"><a-card class="plain-panel" :bordered="false"><div class="section-title"><div><p class="eyebrow">INVENTORY FLOW</p><h2>资产盘点工作流</h2></div></div><div class="workflow-row"><div class="flow-step"><span>1</span><strong>建立盘点任务</strong></div><div class="flow-line"/><div class="flow-step"><span>2</span><strong>扫码盘点</strong></div><div class="flow-line"/><div class="flow-step"><span>3</span><strong>差异复核</strong></div><div class="flow-line"/><div class="flow-step"><span>4</span><strong>处置归档</strong></div></div><a-table class="compact-table" size="small" :pagination="false" :data-source="tasks" :columns="[{title:'盘点任务',dataIndex:'name'},{title:'负责人',dataIndex:'owner'},{title:'进度',dataIndex:'checked_count'},{title:'异常',dataIndex:'exception_count'},{title:'截止日期',dataIndex:'due_date'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='checked_count'"><a-progress :percent="record.total_count ? Math.round(record.checked_count / record.total_count * 100) : 0" size="small"/></template><template v-if="column.dataIndex==='exception_count'"><a-tag :color="record.exception_count ? 'orange' : 'green'">{{ record.exception_count }} 条</a-tag></template></template></a-table></a-card><a-card class="plain-panel" :bordered="false"><div class="section-title"><div><p class="eyebrow">FULL ASSET VIEW</p><h2>全资产分布</h2></div></div><p v-for="category in ['办公设备','IT设备','生产工具','办公家具']" :key="category">{{ category }} <a-progress :percent="Math.min(100, assets.filter(item=>item.category===category).length * 25)" :show-info="false"/></p><a-alert type="info" show-icon message="AI 预留位置" description="后续可接入异常解释、处置建议和资产 Copilot；当前只保留真实业务数据与人工流程。"/></a-card></section></a-tab-pane>
        <a-tab-pane key="ledger" tab="资产台账"><a-card class="plain-panel" :bordered="false"><div class="table-toolbar"><a-input v-model:value="keyword" allow-clear placeholder="搜索编号、名称、部门或责任人"/><a-select v-model:value="statusFilter" :options="statuses.map(value=>({label:value,value}))"/><a-button type="primary" @click="openAsset()"><PlusOutlined/> 新增资产</a-button></div><a-table :data-source="filteredAssets" :pagination="{pageSize:8}" :columns="[{title:'资产编号',dataIndex:'asset_code'},{title:'资产名称',dataIndex:'name'},{title:'类别',dataIndex:'category'},{title:'所属部门',dataIndex:'department'},{title:'责任人',dataIndex:'owner'},{title:'状态',dataIndex:'status'},{title:'操作',dataIndex:'actions'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='status'"><a-tag :color="statusColor[record.status]">{{record.status}}</a-tag></template><template v-if="column.dataIndex==='actions'"><a-space><a-button size="small" @click="openAsset(record)">编辑</a-button><a-button size="small" danger @click="removeAsset(record.id)">删除</a-button></a-space></template></template></a-table></a-card></a-tab-pane>
        <a-tab-pane key="inventory" tab="盘点工作台"><section class="business-grid"><a-card v-for="task in tasks" :key="task.id" class="task-card" :bordered="false"><div class="task-title"><strong>{{task.name}}</strong><a-tag color="processing">{{task.status}}</a-tag></div><p>负责人：{{task.owner}}，截止：{{task.due_date || '未设置'}}</p><a-progress :percent="task.total_count ? Math.round(task.checked_count / task.total_count * 100) : 0"/><div class="task-actions"><a-button><BarcodeOutlined/> 进入扫码</a-button><a-button><ToolOutlined/> 差异复核</a-button></div></a-card><a-empty v-if="!tasks.length" description="暂无盘点任务"/></section></a-tab-pane>
        <a-tab-pane key="exceptions" tab="异常处置"><a-card class="plain-panel" :bordered="false"><a-table :data-source="exceptions" :pagination="false" :columns="[{title:'异常资产',dataIndex:'asset_name'},{title:'所属部门',dataIndex:'department'},{title:'异常类型',dataIndex:'type'},{title:'描述',dataIndex:'description'},{title:'状态',dataIndex:'status'},{title:'操作',dataIndex:'actions'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='status'"><a-tag :color="exceptionColor[record.status]">{{record.status}}</a-tag></template><template v-if="column.dataIndex==='actions'"><a-button size="small" type="primary" :disabled="record.status==='已归档'" @click="openResolve(record)"><CheckCircleOutlined/> 处置归档</a-button></template></template></a-table></a-card></a-tab-pane>
      </a-tabs>
    </a-spin>
    <a-drawer v-model:open="assetDrawerOpen" :title="editingId ? '编辑资产' : '新增资产'" width="520"><a-form layout="vertical"><a-form-item label="资产编号" required><a-input v-model:value="assetForm.asset_code" :disabled="Boolean(editingId)" aria-label="资产编号"/></a-form-item><a-form-item label="资产名称" required><a-input v-model:value="assetForm.name" aria-label="资产名称"/></a-form-item><a-form-item label="类别" required><a-input v-model:value="assetForm.category"/></a-form-item><a-form-item label="所属部门" required><a-input v-model:value="assetForm.department"/></a-form-item><a-form-item label="责任人" required><a-input v-model:value="assetForm.owner"/></a-form-item><a-form-item label="位置" required><a-input v-model:value="assetForm.location"/></a-form-item><a-form-item label="状态"><a-select v-model:value="assetForm.status" :options="statuses.slice(1).map(value=>({label:value,value}))"/></a-form-item><a-form-item label="资产价值"><a-input-number v-model:value="assetForm.value" :min="0" style="width:100%"/></a-form-item><a-button type="primary" block @click="saveAsset">保存资产</a-button></a-form></a-drawer>
    <a-drawer v-model:open="taskDrawerOpen" title="新建盘点任务" width="520"><a-form layout="vertical"><a-form-item label="任务名称" required><a-input v-model:value="taskForm.name"/></a-form-item><a-form-item label="盘点范围" required><a-input v-model:value="taskForm.scope"/></a-form-item><a-form-item label="负责人" required><a-input v-model:value="taskForm.owner"/></a-form-item><a-form-item label="截止日期"><a-input v-model:value="taskForm.due_date" placeholder="YYYY-MM-DD"/></a-form-item><a-button type="primary" block @click="saveTask">创建任务</a-button></a-form></a-drawer>
    <a-modal v-model:open="exceptionModalOpen" title="异常处置归档" @ok="resolveException"><a-textarea v-model:value="resolution" :rows="5" placeholder="填写核实结果、调拨或报废决定"/></a-modal>
  </div>
</template>
